// Parse the free-text deadline field and compute urgency flags.
const item = $input.item.json;
const deadlineRaw = (item['Bid Submission Deadline'] || '').toString().trim();

function parseDeadline(str) {
  if (!str) return null;
  const normalized = str.replace(/(\d{2})-(\w{3})-(\d{4})/, '$2 $1, $3');
  let parsed = Date.parse(normalized);
  if (!isNaN(parsed)) return new Date(parsed);
  parsed = Date.parse(str);
  return isNaN(parsed) ? null : new Date(parsed);
}

const deadlineDate = parseDeadline(deadlineRaw);
const now = new Date();
let daysUntilDeadline = null;
let isPastDeadline = false;
let isUrgent = false;

if (deadlineDate) {
  daysUntilDeadline = Math.ceil((deadlineDate - now) / (1000 * 60 * 60 * 24));
  isPastDeadline = daysUntilDeadline < 0;
  isUrgent = daysUntilDeadline >= 0 && daysUntilDeadline <= 3;
}

return [{
  json: {
    ...item,
    deadlineParsed: deadlineDate ? deadlineDate.toISOString() : null,
    daysUntilDeadline,
    isPastDeadline,
    isUrgent
  }
}];

