// Compare against previously logged tenderIds to avoid regenerating a response.
const form = $('GeM Tender Response Request Form').item.json;
let existingIds = new Set();
try {
  const existingRows = $('Google Sheets - Get Existing Responses').all();
  existingIds = new Set(existingRows.map(r => (r.json.tenderId || '').toString().trim()).filter(Boolean));
} catch (e) {
  existingIds = new Set();
}

const tenderId = (form['Bid Number / Tender ID'] || '').toString().trim();
const isDuplicate = existingIds.has(tenderId);

return [{
  json: {
    ...$input.item.json,
    tenderId,
    isDuplicate
  }
}];

