// Parse the compliance-analysis JSON safely, with a graceful fallback if the model didn't return valid JSON.
const raw = $input.item.json.output || '';
let parsed;
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { items: [], overallCompliancePercent: null, parseError: true };
}

const items = Array.isArray(parsed.items) ? parsed.items : [];
const nonCompliant = items.filter(i => (i.status || '').toLowerCase().includes('not compliant'));
const score = typeof parsed.overallCompliancePercent === 'number' ? parsed.overallCompliancePercent : null;

return [{
  json: {
    complianceItems: items,
    complianceScore: score,
    nonCompliantCount: nonCompliant.length,
    needsReview: score !== null ? score < 60 : true,
    parseError: !!parsed.parseError
  }
}];

