// Merge the tender context, compliance results, and the narrative draft into one record for logging + notifying.
const context = $('Build Tender Context').item.json;
const compliance = $('Parse Compliance Results').item.json;
const narrative = $input.item.json.output || '';

return [{
  json: {
    submissionId: context.submissionId,
    tenderId: context.tenderId,
    tenderTitle: context.tenderTitle,
    complianceScore: compliance.complianceScore,
    nonCompliantCount: compliance.nonCompliantCount,
    isUrgent: context.isUrgent,
    daysUntilDeadline: context.daysUntilDeadline,
    generatedResponse: narrative,
    generatedAt: context.generatedAt
  }
}];

// Build the final tagged notification text used across Telegram/Slack/Gmail.
const p = $input.item.json;
const urgencyTag = p.isUrgent ? ('🔴 URGENT (' + p.daysUntilDeadline + ' days left)') : '🟢 Normal timeline';
const complianceTag = (p.complianceScore !== null && p.complianceScore !== undefined) ? (p.complianceScore + '% compliant') : 'compliance not scored';

const header = '📄 GeM Tender Response Drafted\nSubmission: ' + p.submissionId + '\nTender ID: ' + p.tenderId + '\nTitle: ' + p.tenderTitle + '\n' + urgencyTag + ' | ' + complianceTag + '\n\n';

return [{
  json: {
    ...p,
    notificationText: header + p.generatedResponse
  }
}];
